const heroTitle=document.querySelector('.hero h1');
heroTitle.innerHTML='<span class="name-word">'+[...'Roshan'].map((c,i)=>`<span class="name-letter" style="--i:${i}">${c}</span>`).join('')+'</span> <span class="hero-amp">&</span> <span class="name-word">'+[...'Hannath'].map((c,i)=>`<span class="name-letter" style="--i:${i+7}">${c}</span>`).join('')+'</span>';
heroTitle.setAttribute('aria-label','Roshan and Hannath');heroTitle.querySelectorAll('span').forEach(s=>s.setAttribute('aria-hidden','true'));
const sentence=document.querySelector('.story-words');sentence.innerHTML=sentence.textContent.trim().split(/\s+/).map(w=>`<span>${w}</span>`).join(' ');
const words=[...sentence.querySelectorAll('span')],story=document.querySelector('.scroll-story'),hero=document.querySelector('.hero'),garden=document.querySelector('.garden'),heroCopy=document.querySelector('.hero-copy'),progress=document.querySelector('.reading-progress'),paper=document.querySelector('.date-paper');
let scrollFrame=0;
function renderScroll(){scrollFrame=0;const y=scrollY,h=innerHeight;const max=document.documentElement.scrollHeight-h;progress.style.transform=`scaleX(${max>0?y/max:0})`;if(paused||reduced.matches){words.forEach(w=>w.classList.add('lit'));return;}const rect=hero.getBoundingClientRect();if(rect.bottom>0){const p=Math.max(0,-rect.top/rect.height);garden.style.transform=`translateY(${p*75}px) scale(${1+p*.08})`;heroCopy.style.transform=`translateY(${p*-55}px)`;heroCopy.style.opacity=String(Math.max(0,1-p*1.3));}const sr=story.getBoundingClientRect();const p=Math.max(0,Math.min(1,-sr.top/(story.offsetHeight-h)));words.forEach((w,i)=>w.classList.toggle('lit',i/words.length<=p*1.25));story.style.setProperty('--orbit',`${p*100}deg`);const pr=paper.getBoundingClientRect();if(pr.top<h&&pr.bottom>0)paper.style.transform=`rotate(${Math.max(-5,Math.min(3,(pr.top/h-.5)*10))}deg)`;}
function queueScroll(){if(!scrollFrame)scrollFrame=requestAnimationFrame(renderScroll)}addEventListener('scroll',queueScroll,{passive:true});addEventListener('resize',queueScroll);motion.addEventListener('click',queueScroll);reduced.addEventListener('change',queueScroll);renderScroll();
const seal=document.querySelector('.seal');seal.addEventListener('click',()=>{const open=document.querySelector('.envelope').classList.toggle('open');seal.setAttribute('aria-expanded',String(open));seal.setAttribute('aria-label',open?'Fold the letter':'Open the letter');document.querySelector('.letter-hint').textContent=open?'A LITTLE NOTE, WITH ALL OUR LOVE':'TAP THE SEAL TO UNFOLD';});
document.querySelectorAll('.wish-card,.letter-section .reveal').forEach(el=>observer.observe(el));
const digits=document.querySelectorAll('.timer div>span');const digitObserver=new MutationObserver(records=>{if(paused||reduced.matches)return;records.forEach(r=>{const el=r.target.nodeType===3?r.target.parentElement:r.target;if(el.matches('.timer div>span')){el.classList.remove('tick');requestAnimationFrame(()=>el.classList.add('tick'));}})});digits.forEach(el=>digitObserver.observe(el,{childList:true,characterData:true,subtree:true}));
